#include <linux/videodev2.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>
#include <poll.h>
#include <sys/epoll.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <dlfcn.h>
#include <xf86drm.h>
// Run in the Quest guest with the adapter preloaded and an Annex-B red frame
// generated by ffmpeg. Exercises Steam's headless allocation path, real
// MediaCodec, queueing, timestamps and decoded pixels on actual hardware.
int main(int argc,char** argv){
 assert(argc==2||argc==5);unsigned width=argc==5?atoi(argv[2]):128,height=argc==5?atoi(argv[3]):128;bool hevc=argc==5&&!strcmp(argv[4],"hevc");assert(width>=128&&height>=128);int fd=open("/dev/video0",O_RDWR);assert(fd>=0);
 v4l2_capability caps{};assert(!ioctl(fd,VIDIOC_QUERYCAP,&caps));assert(strstr((char*)caps.driver,"quest-mediacodec"));
 v4l2_format fmt{};fmt.type=V4L2_BUF_TYPE_VIDEO_OUTPUT_MPLANE;fmt.fmt.pix_mp.width=width;fmt.fmt.pix_mp.height=height;fmt.fmt.pix_mp.pixelformat=hevc?V4L2_PIX_FMT_HEVC:V4L2_PIX_FMT_H264;assert(!ioctl(fd,VIDIOC_S_FMT,&fmt));
 v4l2_requestbuffers req{};req.type=V4L2_BUF_TYPE_VIDEO_OUTPUT_MPLANE;req.memory=V4L2_MEMORY_MMAP;req.count=3;assert(!ioctl(fd,VIDIOC_REQBUFS,&req));
 v4l2_plane plane{};v4l2_buffer b{};b.type=req.type;b.memory=req.memory;b.m.planes=&plane;b.length=1;assert(!ioctl(fd,VIDIOC_QUERYBUF,&b));
 auto input=(unsigned char*)mmap(nullptr,plane.length,PROT_READ|PROT_WRITE,MAP_SHARED,fd,plane.m.mem_offset);assert(input!=MAP_FAILED);size_t inputSize=plane.length;
 FILE* sample=fopen(argv[1],"rb");assert(sample);size_t size=fread(input,1,inputSize,sample);fclose(sample);assert(size>0);
 bool stateful=getenv("QUEST_VIDEO_STATEFUL")!=nullptr;int epoll=-1;
 if(stateful){
  FILE* path=popen("vrdevice_path video_decode","r");assert(path);char name[32];assert(fgets(name,sizeof(name),path)&&!strcmp(name,"/dev/video0\n")&&!pclose(path));
  epoll=epoll_create1(EPOLL_CLOEXEC);assert(epoll>=0);epoll_event event{};event.events=EPOLLIN|EPOLLPRI|EPOLLOUT;event.data.u64=123;
  assert(!epoll_ctl(epoll,EPOLL_CTL_ADD,fd,&event));
  int type=V4L2_BUF_TYPE_VIDEO_OUTPUT_MPLANE;assert(!ioctl(fd,VIDIOC_STREAMON,&type));
  plane={};plane.bytesused=size;plane.length=inputSize;b={};b.type=type;b.memory=V4L2_MEMORY_MMAP;b.m.planes=&plane;b.length=1;b.timestamp.tv_usec=12345;assert(!ioctl(fd,VIDIOC_QBUF,&b));
  bool changed=false;for(int attempts=0;attempts<20&&!changed;attempts++){
   assert(epoll_wait(epoll,&event,1,5000)==1&&event.data.u64==123);
   if(event.events&EPOLLOUT){plane={};b={};b.type=type;b.m.planes=&plane;b.length=1;assert(!ioctl(fd,VIDIOC_DQBUF,&b));}
   if(event.events&EPOLLPRI){v4l2_event source{};assert(!ioctl(fd,VIDIOC_DQEVENT,&source)&&source.type==V4L2_EVENT_SOURCE_CHANGE);changed=true;}
  }assert(changed);
  fmt={};fmt.type=V4L2_BUF_TYPE_VIDEO_CAPTURE_MPLANE;assert(!ioctl(fd,VIDIOC_G_FMT,&fmt));assert(fmt.fmt.pix_mp.width==width&&fmt.fmt.pix_mp.height==height);
 }
 fmt={};fmt.type=V4L2_BUF_TYPE_VIDEO_CAPTURE_MPLANE;fmt.fmt.pix_mp.width=width;fmt.fmt.pix_mp.height=height;fmt.fmt.pix_mp.pixelformat=V4L2_PIX_FMT_NV12;assert(!ioctl(fd,VIDIOC_S_FMT,&fmt));
 req={};req.type=fmt.type;req.memory=V4L2_MEMORY_DMABUF;req.count=3;assert(!ioctl(fd,VIDIOC_REQBUFS,&req));
 int capture[3];unsigned char* output[3];size_t bytes=width*height*3/2;
 void* drm=dlopen("/opt/quest/libquest_streaming_drm.so",RTLD_NOW|RTLD_LOCAL);assert(drm);
 auto drmIoctl=(int(*)(int,unsigned long,void*))dlsym(drm,"drmIoctl");assert(drmIoctl);
 for(int i=0;i<3;i++){
  drm_mode_create_dumb buffer{};buffer.width=width;buffer.height=height;buffer.bpp=16;
  assert(!drmIoctl(-1,DRM_IOCTL_MODE_CREATE_DUMB,&buffer)&&buffer.size>=bytes);
  drm_prime_handle exported{};exported.handle=buffer.handle;exported.flags=DRM_CLOEXEC;
  assert(!drmIoctl(-1,DRM_IOCTL_PRIME_HANDLE_TO_FD,&exported));capture[i]=exported.fd;
  // Steam destroys the original handle immediately after exporting it.
  drm_mode_destroy_dumb destroyed{buffer.handle};assert(!drmIoctl(-1,DRM_IOCTL_MODE_DESTROY_DUMB,&destroyed));
  output[i]=(unsigned char*)mmap(nullptr,bytes,PROT_READ|PROT_WRITE,MAP_SHARED,capture[i],0);assert(output[i]!=MAP_FAILED);
  plane={};plane.m.fd=capture[i]; // Steam's DMABUF queue leaves length zero.
  b={};b.index=i;b.type=req.type;b.memory=req.memory;b.m.planes=&plane;b.length=1;
  assert(!ioctl(fd,VIDIOC_QBUF,&b)&&plane.length==buffer.size&&plane.m.fd==capture[i]);
 }
 int type=V4L2_BUF_TYPE_VIDEO_OUTPUT_MPLANE;assert(!ioctl(fd,VIDIOC_STREAMON,&type));type=V4L2_BUF_TYPE_VIDEO_CAPTURE_MPLANE;assert(!ioctl(fd,VIDIOC_STREAMON,&type));
 if(!stateful){plane={};plane.bytesused=size;plane.length=inputSize;b={};b.type=V4L2_BUF_TYPE_VIDEO_OUTPUT_MPLANE;b.memory=V4L2_MEMORY_MMAP;b.m.planes=&plane;b.length=1;b.timestamp.tv_usec=12345;assert(!ioctl(fd,VIDIOC_QBUF,&b));}
 pollfd event{fd,POLLIN,0};assert(poll(&event,1,5000)==1&&(event.revents&POLLIN));
 plane={};b={};b.type=V4L2_BUF_TYPE_VIDEO_CAPTURE_MPLANE;b.memory=V4L2_MEMORY_DMABUF;b.m.planes=&plane;b.length=1;assert(!ioctl(fd,VIDIOC_DQBUF,&b));assert(b.index<3&&b.timestamp.tv_usec==12345&&plane.bytesused==bytes);
 auto pixels=output[b.index];fprintf(stderr,"Decoded NV12: Y=%u U=%u V=%u timestamp=%ld\n",pixels[0],pixels[width*height],pixels[width*height+1],b.timestamp.tv_usec);
 assert(abs(int(pixels[0])-81)<6&&abs(int(pixels[width*height])-90)<6&&abs(int(pixels[width*height+1])-240)<6);
 if(epoll>=0){assert(!epoll_ctl(epoll,EPOLL_CTL_DEL,fd,nullptr));close(epoll);}close(fd);munmap(input,inputSize);for(int i=0;i<3;i++){munmap(output[i],bytes);close(capture[i]);}
 dlclose(drm);puts("PASS: headless buffers, V4L2 adapter, Android decode, timestamp and NV12 pixels");
}
